def S(k):
    n = 11
    if k < 1 or k > n:
        return -1
    # Assuming k <= 10, so 10-k >= 0
    return k * (n - k) * (10 - k)

values = {}
for k in range(1, 11):
    values[k] = S(k)

print(values)
print(max(values.values()))

